import React, { Component } from "react";
import moment from "moment";

export class UserCard extends Component {
    render() {console.log("this.props",this.props);
        return (
          
            <div className="card card-user">
                <div className="image">
                    <img src={this.props.bgImage} alt="..." />
                </div>
                <div className="content">
                    <div className="author">
                        <a href="#pablo">
                            <img
                                className="avatar border-gray"
                                src={this.props.photo !=="" ?this.props.photo : "data:image/png;base64,"}
                                alt="..."
                            />  
                            <div className="content">
                            <h4 className="title">
                                {this.props.firstName}
                                <br />
                                <small>{this.props.surName}</small>
                                </h4>
                                <br />
                                Email: {this.props.email}
                                <br />
                                Date of Birth: {moment(this.props.dob).format('DD MMM YYYY')}
                                <br />
                                City: {this.props.city}
                                <br />
                                Zip: {this.props.zip}
                                <br />
                                Address: {this.props.address}
                                </div>
                        </a>
                    </div>
                    <p className="description text-center">{this.props.role}</p>
                </div>
                <hr />
                <div className="text-center">{this.props.socials}</div>
            </div>
        );
    }
}

export default UserCard;
